set -eu
export PGPASSFILE=/etc/branch_stock/stock_app.pgpass
psql -X -v ON_ERROR_STOP=1 -h 10.100.127.10 -U stock_app -d branch_stock <<'SQL'
SELECT current_user, current_database();
TABLE stock;
BEGIN;
UPDATE stock SET quantity=quantity+1 WHERE sku='PAPER';
SELECT sku,quantity FROM stock WHERE sku='PAPER';
ROLLBACK;
SELECT sku,quantity FROM stock WHERE sku='PAPER';
SQL

