set -eu
printf 'boot_id='; cat /proc/sys/kernel/random/boot_id
. /etc/os-release; printf 'os=%s kernel=' "$PRETTY_NAME"; uname -r
printf '%s\n' '--- installed database packages ---'
rpm -q postgresql postgresql-server postgresql-private-libs
printf '%s\n' '--- service/security/listeners ---'
printf 'postgres='; systemctl is-active postgresql
printf 'postgres_enabled='; systemctl is-enabled postgresql
printf 'sshd='; systemctl is-active sshd
printf 'firewalld='; systemctl is-active firewalld
printf 'selinux='; getenforce
ss -lntp
firewall-cmd --list-rich-rules
printf '%s\n' '--- data and effective privileges ---'
sudo -u postgres psql -XAt -d branch_stock <<'SQL'
SELECT 'stock='||string_agg(sku||':'||quantity,',' ORDER BY sku) FROM stock;
SELECT 'supplier_costs='||string_agg(sku||':'||cost,',' ORDER BY sku) FROM supplier_costs;
SELECT 'stock_app_stock_select='||has_table_privilege('stock_app','public.stock','SELECT');
SELECT 'stock_app_quantity_update='||has_column_privilege('stock_app','public.stock','quantity','UPDATE');
SELECT 'stock_app_sku_update='||has_column_privilege('stock_app','public.stock','sku','UPDATE');
SELECT 'stock_app_cost_select='||has_table_privilege('stock_app','public.supplier_costs','SELECT');
SELECT 'stock_app_schema_create='||has_schema_privilege('stock_app','public','CREATE');
SELECT 'auditor_stock_select='||has_table_privilege('auditor','public.stock','SELECT');
SELECT 'auditor_cost_select='||has_table_privilege('auditor','public.supplier_costs','SELECT');
SELECT 'auditor_stock_update='||has_table_privilege('auditor','public.stock','UPDATE');
SELECT 'auditor_schema_create='||has_schema_privilege('auditor','public','CREATE');
SELECT 'unexpected_probe_tables='||count(*) FROM pg_tables WHERE schemaname='public' AND tablename LIKE '%probe%';
SELECT 'hba_errors='||count(*) FROM pg_hba_file_rules WHERE error IS NOT NULL;
SQL
printf '%s\n' '--- protected/source and rollback material ---'
sha256sum /srv/legacy2/database-reader-writer-roles/stock.sql
stat -c '%a %U:%G %n' /etc/branch_stock /etc/branch_stock/credential_salt /var/lib/pgsql/data/postgresql.conf.pre-branch-stock /var/lib/pgsql/data/pg_hba.conf.pre-branch-stock
test ! -e /var/lib/pgsql/branch_stock_roles.sql
test ! -e /run/stock_app_denials.out
test ! -e /run/auditor_denials.out
printf '%s\n' 'temporary artifacts absent'

